widget.solution:
import numpy as np

def diffusion_coefficient(dx, dt):
    return dx * dx / (2 * dt)

def walk_density(n):
    """Probabilities at sites -n..n after n steps."""
    p = np.zeros(2 * n + 1)
    p[n] = 1.0
    for _ in range(n):
        q = np.zeros_like(p)
        q[1:] += 0.5 * p[:-1]
        q[:-1] += 0.5 * p[1:]
        p = q
    return p
